import os
import xml.etree.ElementTree as ET

NS = {
    "p": "http://schemas.openxmlformats.org/presentationml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "ct": "http://schemas.openxmlformats.org/package/2006/content-types",
    "pr": "http://schemas.openxmlformats.org/package/2006/relationships",
}

errors = []

# 1. All XML files parse
for root, _, files in os.walk("unpacked"):
    for fn in files:
        if fn.endswith(".xml") or fn.endswith(".rels"):
            p = os.path.join(root, fn)
            try:
                ET.parse(p)
            except ET.ParseError as e:
                errors.append("parse error %s: %s" % (p, e))

# 2. slide6.xml exists and is well-formed; contains ctrTitle text
t = ET.parse("unpacked/ppt/slides/slide6.xml").getroot()
texts = [el.text for el in t.iter() if el.tag.endswith("}t") and el.text]
if texts != ["Thank you for your attention"]:
    errors.append("slide6 text unexpected: %r" % texts)

# 3. slide6 rels -> slideLayout1 exists
r = ET.parse("unpacked/ppt/slides/_rels/slide6.xml.rels").getroot()
targets = [rel.get("Target") for rel in r]
if targets != ["../slideLayouts/slideLayout1.xml"]:
    errors.append("slide6 rels unexpected: %r" % targets)
if not os.path.exists("unpacked/ppt/slideLayouts/slideLayout1.xml"):
    errors.append("slideLayout1.xml missing")

# 4. Content_Types declares slide6
ct = ET.parse("unpacked/[Content_Types].xml").getroot()
overrides = {o.get("PartName") for o in ct.findall("ct:Override", NS)}
if "/ppt/slides/slide6.xml" not in overrides:
    errors.append("slide6 not declared in [Content_Types].xml")

# 5. presentation.xml.rels has rId13 -> slide6
rels = ET.parse("unpacked/ppt/_rels/presentation.xml.rels").getroot()
rmap = {rel.get("Id"): rel.get("Target") for rel in rels}
if rmap.get("rId13") != "slides/slide6.xml":
    errors.append("rId13 missing/wrong in presentation.xml.rels: %r" % rmap.get("rId13"))

# 6. presentation.xml sldIdLst contains id 261 -> rId13, after 260
pres = ET.parse("unpacked/ppt/presentation.xml").getroot()
ids = [(s.get("id"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"))
       for s in pres.find("p:sldIdLst", NS)]
if ("261", "rId13") not in ids:
    errors.append("sldId 261/rId13 missing in sldIdLst: %r" % ids)
if ids[-1] != ("261", "rId13"):
    errors.append("slide6 not last in sldIdLst: %r" % ids)

print("sldIdLst:", ids)
print("rel map rId13:", rmap.get("rId13"))
print("slide6 texts:", texts)
if errors:
    for e in errors:
        print("ERROR:", e)
    raise SystemExit(1)
print("OK: package structure valid")

